(()=>{ 
"use strict";
const bridge=window.NetworkMapBridge;
if(!bridge)return;
const map=bridge.map,container=map.getContainer(),$=id=>document.getElementById(id);
const rectangleButton=$("select-rectangle"),polygonButton=$("select-polygon"),finishButton=$("finish-polygon"),cancelButton=$("cancel-selection"),exportButton=$("export-kmz"),state=$("export-state"),readyLabel=$("export-ready-label");
let mode=null,points=[],shape=null,ready=false,features=[],dragStart=null;
const escapeXml=value=>String(value??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&apos;"}[c]));
function update(){rectangleButton.classList.toggle("active",mode==="rectangle");polygonButton.classList.toggle("active",mode==="polygon");finishButton.disabled=mode!=="polygon"||points.length<3;cancelButton.disabled=!mode&&!shape;exportButton.disabled=!ready||!features.length;readyLabel.hidden=!ready||!features.length}
function removeShape(){if(shape){map.removeLayer(shape);shape=null}points=[];ready=false;features=[];update()}
function stop(){mode=null;container.classList.remove("area-selecting","area-rectangle-drag");map.doubleClickZoom.enable();map.dragging.enable();update()}
function begin(next){if(bridge.isMeasuring())bridge.setMeasuring(false);removeShape();mode=next;map.closePopup();container.classList.add("area-selecting");if(next==="polygon"){map.doubleClickZoom.disable();state.textContent="Atinge succesiv punctele poligonului, apoi apasă Finalizează."}else{container.classList.add("area-rectangle-drag");state.textContent="Trage pe hartă pentru a desena dreptunghiul."}update()}
function draw(){if(shape)map.removeLayer(shape);if(mode==="rectangle"&&points.length===2)shape=L.rectangle(L.latLngBounds(points),{color:"#d99400",weight:2,dashArray:"7 5",fillColor:"#ffc34b",fillOpacity:.16,interactive:false}).addTo(map);else if(points.length>=2)shape=(points.length>=3?L.polygon(points,{color:"#d99400",weight:2,dashArray:"7 5",fillColor:"#ffc34b",fillOpacity:.16,interactive:false}):L.polyline(points,{color:"#d99400",weight:2,dashArray:"7 5",interactive:false})).addTo(map);update()}
function ring(){if(mode==="rectangle"&&points.length===2){const b=L.latLngBounds(points),a=b.getSouthWest(),z=b.getNorthEast();return[[a.lat,a.lng],[z.lat,a.lng],[z.lat,z.lng],[a.lat,z.lng]]}return points.map(p=>[p.lat,p.lng])}
function bounds(r){const xs=r.map(p=>p[1]),ys=r.map(p=>p[0]);return[Math.min(...xs),Math.min(...ys),Math.max(...xs),Math.max(...ys)]}
function pointInside(p,r){let yes=false;for(let i=0,j=r.length-1;i<r.length;j=i++){const a=r[i],b=r[j];if((a[0]>p[1])!==(b[0]>p[1])&&p[0]<(b[1]-a[1])*(p[1]-a[0])/(b[0]-a[0])+a[1])yes=!yes}return yes}
function orient(a,b,c){return(b[0]-a[0])*(c[1]-a[1])-(b[1]-a[1])*(c[0]-a[0])}
function crosses(a,b,c,d){const o1=orient(a,b,c),o2=orient(a,b,d),o3=orient(c,d,a),o4=orient(c,d,b),on=(p,q,r)=>q[0]>=Math.min(p[0],r[0])&&q[0]<=Math.max(p[0],r[0])&&q[1]>=Math.min(p[1],r[1])&&q[1]<=Math.max(p[1],r[1]);return o1*o2<0&&o3*o4<0||o1===0&&on(a,c,b)||o2===0&&on(a,d,b)||o3===0&&on(c,a,d)||o4===0&&on(c,b,d)}
function coordInRing(p,r){let yes=false;for(let i=0,j=r.length-1;i<r.length;j=i++){const a=r[i],b=r[j];if((a[1]>p[1])!==(b[1]>p[1])&&p[0]<(b[0]-a[0])*(p[1]-a[1])/(b[1]-a[1])+a[0])yes=!yes}return yes}
function intersects(g,r){if(!g)return false;if(g.type==="GeometryCollection")return(g.geometries||[]).some(x=>intersects(x,r));const isPoint=p=>Array.isArray(p)&&typeof p[0]==="number";if(g.type==="Point")return pointInside(g.coordinates,r);if(g.type==="MultiPoint")return g.coordinates.some(p=>pointInside(p,r));let lines=[],polys=[];if(g.type==="LineString")lines=[g.coordinates];if(g.type==="MultiLineString")lines=g.coordinates;if(g.type==="Polygon"){lines=g.coordinates;polys=[g.coordinates]}if(g.type==="MultiPolygon"){lines=g.coordinates.flat();polys=g.coordinates}for(const line of lines){if(line.some(p=>isPoint(p)&&pointInside(p,r)))return true;for(let i=1;i<line.length;i++)for(let j=0;j<r.length;j++){const a=line[i-1],b=line[i],c=[r[j][1],r[j][0]],d=[r[(j+1)%r.length][1],r[(j+1)%r.length][0]];if(isPoint(a)&&isPoint(b)&&crosses(a,b,c,d))return true}}return polys.some(poly=>poly[0]?.some(p=>pointInside(p,r))||r.some(p=>poly[0]&&coordInRing([p[1],p[0]],poly[0])))}
function overlaps(a,b){return !a||!(a[2]<b[0]||a[0]>b[2]||a[3]<b[1]||a[1]>b[3])}
async function prepare(){const manifest=bridge.getManifest();const r=ring();if(!manifest||r.length<3){state.textContent="Zona nu este validă.";return}stop();ready=false;features=[];update();state.textContent="Se caută elementele din zona selectată…";const box=bounds(r),found=[];for(const layer of manifest.layers.filter(l=>bridge.active.has(l.id))){try{let data;if(layer.shards){const chunks=layer.shards.filter(s=>overlaps(s.bounds,box));const parts=await Promise.all(chunks.map(s=>bridge.getData({id:layer.id+":"+s.file,file:s.file})));data={features:parts.flatMap(x=>x.features)}}else data=await bridge.getData(layer);for(const f of data.features||[])if(intersects(f.geometry,r))found.push({feature:f,layer})}catch{}}features=found;ready=true;state.textContent=found.length?found.length.toLocaleString("ro")+" elemente găsite în "+new Set(found.map(x=>x.layer.id)).size+" layere bifate.":"Nu sunt elemente în zonă din layerele bifate.";update()}
function colorOf(feature,layer){const c=bridge.featureColor(feature,layer);return/^#[0-9a-f]{6}$/i.test(c)?c:"#287ca8"}
function kmlColor(hex,alpha=1){const h=hex.slice(1),a=Math.round(alpha*255).toString(16).padStart(2,"0");return(a+h.slice(4,6)+h.slice(2,4)+h.slice(0,2)).toLowerCase()}
function coordinateText(coords){return coords.map(p=>p[0]+","+p[1]+","+(p[2]||0)).join(" ")}
function geometry(g){if(!g)return"";if(g.type==="GeometryCollection")return"<MultiGeometry>"+(g.geometries||[]).map(geometry).join("")+"</MultiGeometry>";if(g.type==="Point")return"<Point><coordinates>"+coordinateText([g.coordinates])+"</coordinates></Point>";if(g.type==="MultiPoint")return"<MultiGeometry>"+g.coordinates.map(p=>geometry({type:"Point",coordinates:p})).join("")+"</MultiGeometry>";if(g.type==="LineString")return"<LineString><tessellate>1</tessellate><coordinates>"+coordinateText(g.coordinates)+"</coordinates></LineString>";if(g.type==="MultiLineString")return"<MultiGeometry>"+g.coordinates.map(p=>geometry({type:"LineString",coordinates:p})).join("")+"</MultiGeometry>";if(g.type==="Polygon"){const rings=g.coordinates||[];return"<Polygon><outerBoundaryIs><LinearRing><coordinates>"+coordinateText(rings[0]||[])+"</coordinates></LinearRing></outerBoundaryIs>"+rings.slice(1).map(p=>"<innerBoundaryIs><LinearRing><coordinates>"+coordinateText(p)+"</coordinates></LinearRing></innerBoundaryIs>").join("")+"</Polygon>"}if(g.type==="MultiPolygon")return"<MultiGeometry>"+g.coordinates.map(p=>geometry({type:"Polygon",coordinates:p})).join("")+"</MultiGeometry>";return""}
function makeKml(){const styles=new Map(),marks=features.map(({feature,layer})=>{const p=feature.properties||{},color=colorOf(feature,layer),sid="s"+color.slice(1),name=p.n||p.name||p.Name||feature.id||layer.name;styles.set(sid,color);const values=Object.entries(p).filter(([k,v])=>!k.startsWith("_")&&v!==null&&v!=="");const rows=values.map(([k,v])=>"<tr><th>"+escapeXml(k)+"</th><td>"+escapeXml(typeof v==="object"?JSON.stringify(v):v)+"</td></tr>").join("");return"<Placemark><name>"+escapeXml(name)+"</name><styleUrl>#"+sid+"</styleUrl><description><![CDATA[<b>"+escapeXml(layer.name)+"</b><table>"+rows+"</table>]]></description><ExtendedData><Data name=\"Layer\"><value>"+escapeXml(layer.name)+"</value></Data>"+values.map(([k,v])=>"<Data name=\""+escapeXml(k)+"\"><value>"+escapeXml(typeof v==="object"?JSON.stringify(v):v)+"</value></Data>").join("")+"</ExtendedData>"+geometry(feature.geometry)+"</Placemark>"}).join("");const styleXml=[...styles].map(([id,c])=>"<Style id=\""+id+"\"><IconStyle><color>"+kmlColor(c)+"</color><scale>0.9</scale><Icon><href>https://maps.google.com/mapfiles/kml/shapes/placemark_circle.png</href></Icon></IconStyle><LineStyle><color>"+kmlColor(c)+"</color><width>3</width></LineStyle><PolyStyle><color>"+kmlColor(c,.25)+"</color></PolyStyle></Style>").join("");return'<?xml version="1.0" encoding="UTF-8"?><kml xmlns="http://www.opengis.net/kml/2.2"><Document><name>OROC - elemente rețea</name>'+styleXml+"<Folder><name>Selecție</name>"+marks+"</Folder></Document></kml>"}
function kmz(kml){const enc=new TextEncoder(),bytes=enc.encode(kml),name=enc.encode("doc.kml"),table=new Uint32Array(256);for(let n=0;n<256;n++){let c=n;for(let k=0;k<8;k++)c=c&1?0xedb88320^(c>>>1):c>>>1;table[n]=c>>>0}let crc=0xffffffff;for(const b of bytes)crc=table[(crc^b)&255]^(crc>>>8);crc=(crc^0xffffffff)>>>0;const local=new Uint8Array(30+name.length),lv=new DataView(local.buffer);lv.setUint32(0,0x04034b50,true);lv.setUint16(4,20,true);lv.setUint16(6,0x800,true);lv.setUint32(14,crc,true);lv.setUint32(18,bytes.length,true);lv.setUint32(22,bytes.length,true);lv.setUint16(26,name.length,true);local.set(name,30);const dir=new Uint8Array(46+name.length),dv=new DataView(dir.buffer);dv.setUint32(0,0x02014b50,true);dv.setUint16(4,20,true);dv.setUint16(6,20,true);dv.setUint16(8,0x800,true);dv.setUint32(16,crc,true);dv.setUint32(20,bytes.length,true);dv.setUint32(24,bytes.length,true);dv.setUint16(28,name.length,true);dir.set(name,46);const end=new Uint8Array(22),ev=new DataView(end.buffer);ev.setUint32(0,0x06054b50,true);ev.setUint16(8,1,true);ev.setUint16(10,1,true);ev.setUint32(12,dir.length,true);ev.setUint32(16,local.length+bytes.length,true);return new Blob([local,bytes,dir,end],{type:"application/vnd.google-earth.kmz"})}
function download(){if(!ready||!features.length)return;const url=URL.createObjectURL(kmz(makeKml())),a=document.createElement("a");a.href=url;a.download="OROC_elemente_retea_"+new Date().toISOString().slice(0,10)+".kmz";document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000)}
rectangleButton.addEventListener("click",()=>begin("rectangle"));polygonButton.addEventListener("click",()=>begin("polygon"));finishButton.addEventListener("click",()=>{if(mode==="polygon"&&points.length>=3)prepare()});cancelButton.addEventListener("click",()=>{stop();removeShape();state.textContent="Selecția a fost anulată."});exportButton.addEventListener("click",download);
container.addEventListener("pointerdown",e=>{if(mode!=="rectangle"||e.button!==0)return;e.preventDefault();e.stopPropagation();dragStart=map.mouseEventToLatLng(e);points=[dragStart,dragStart];map.dragging.disable();container.setPointerCapture?.(e.pointerId);draw()},{capture:true});document.addEventListener("pointermove",e=>{if(!dragStart||mode!=="rectangle")return;e.preventDefault();points[1]=map.mouseEventToLatLng(e);draw()},{capture:true});document.addEventListener("pointerup",e=>{if(!dragStart||mode!=="rectangle")return;e.preventDefault();points[1]=map.mouseEventToLatLng(e);dragStart=null;map.dragging.enable();draw();const b=L.latLngBounds(points);if(b.getNorthEast().distanceTo(b.getSouthWest())<10){state.textContent="Trage o zonă mai mare pentru dreptunghi.";return}prepare()},{capture:true});
map.on("click",e=>{if(mode==="polygon"){points.push(e.latlng);draw()}});
document.addEventListener("keydown",e=>{if(e.key==="Escape"&&(mode||shape)){if(mode)stop();if(shape){removeShape();state.textContent="Selecția a fost anulată."}}});
})();